function petNavArt(kind){const pet=heroSVG(profile.hero),other=HEROES.find(h=>h.id.startsWith(profile.hero.startsWith('dog')?'cat':'dog'))||HEROES[0];if(kind==='heroes')return `<span aria-hidden="true" class="pet-nav-art pet-nav-face">${pet}</span>`;if(kind==='live')return `<span aria-hidden="true" class="pet-nav-art pet-nav-duo">${pet}${heroSVG(other.id)}</span>`;const shapes={home:'<path d="M18 25Q10 25 8 39L5 52Q4 62 12 62L25 50H47L60 62Q68 62 67 52L64 39Q62 25 54 25Z" fill="#a4dec5"/><path d="M19 34v16m-8-8h16"/><circle cx="49" cy="37" r="3" fill="#f7bd69"/><circle cx="57" cy="45" r="3" fill="#eb9da9"/>',progress:'<path d="M23 12h28v20Q51 49 37 49T23 32Z" fill="#f5ce79"/><path d="M23 19H12v10q0 12 14 12m25-22h11v10q0 12-14 12M37 49v12M24 65h26"/><path d="m37 20 4 7 8 1-6 5 2 8-8-4-7 4 1-8-6-5 8-1Z" fill="#fff1bd"/>',guide:'<path d="M37 23Q23 12 7 19v43q16-7 30 3 15-10 30-3V19Q51 12 37 23Z" fill="#a9cdea"/><path d="M37 23v42M15 29l14 4m-14 6 14 4m17-10 13-4m-13 14 13-4"/>'};return `<span aria-hidden="true" class="pet-nav-art"><svg viewBox="0 0 74 78" aria-hidden="true"><g stroke="#22394a" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round">${shapes[kind]||shapes.home}</g></svg></span>`}
function refreshPetNavigation(){document.querySelectorAll('.sidebar nav .nav').forEach(b=>{const kind=b.dataset.live?'live':b.dataset.page,label=({home:'Play',heroes:'Avatars',progress:'My progress',guide:'How to play',live:'Play live with friends'})[kind];b.innerHTML=petNavArt(kind)+`<span class="pet-nav-label">${label}</span>`})}
const petNavBar=updateBar;updateBar=function(){petNavBar();refreshPetNavigation()};
function weaponIllustration(w,large=false){const i=Math.max(0,WEAPONS.indexOf(w));return `<svg class="weapon-illustration ${large?'weapon-animated':''}" viewBox="0 0 280 160" role="img" aria-label="${w.name}"><ellipse cx="130" cy="139" rx="90" ry="10" fill="#071b3266"/><g class="weapon-body" stroke="#183449" stroke-width="5" stroke-linejoin="round"><path d="M100 77h36l-8 52h-27Z" fill="#e0c497"/><path d="M48 53Q39 53 39 67v34h40l16-18h88V48H88L75 53Z" fill="${w.colour}"/><path d="M92 49h48V32h-35Z" fill="#ddeded"/><rect x="145" y="54" width="70" height="25" rx="6" fill="#7396ad"/>${Array.from({length:Math.min(3,w.shots)},(_,n)=>`<rect x="194" y="${48+n*14}" width="39" height="10" rx="4" fill="${w.colour}"/>`).join('')}<circle cx="${84+i*5}" cy="67" r="${10+i}" fill="#f8e9aa"/><path d="M51 64v23m10-23v23" stroke="#eefaff" stroke-width="3"/></g><g class="weapon-pulse" fill="${w.colour}"><path d="m238 58 15-8-5 12 22 2-22 8 5 12-15-9Z"/></g></svg>`}
armoury=function(){if(live){toast('Leave your live room before changing equipment.');return}const selected=weaponFor();openModal(`${topModal('THE ARMOURY')}<h2 id="modal-title">Find your favourite play style.</h2><p class="sub">Tap a weapon to enlarge its firing animation. Previewing does not equip it.</p><div class="weapon-grid">${WEAPONS.map(w=>`<article class="weapon-card ${selected.id===w.id?'selected':''}" style="--weapon-colour:${w.colour}"><button class="weapon-preview-button" data-weapon-preview="${w.id}" aria-label="Enlarge and animate ${w.name}">${weaponIllustration(w)}</button><h3>${w.name}</h3><p>${w.desc}</p><small>${w.shots} projectile${w.shots===1?'':'s'} · ${w.range} range · ${w.pierce?'Piercing':'Standard'}</small><button class="secondary" data-weapon="${w.id}" ${playerLevel()<w.level?'disabled':''}>${playerLevel()<w.level?'Unlock at level '+w.level:selected.id===w.id?'Equipped ✓':'Equip'}</button></article>`).join('')}</div><button class="secondary" data-custom="hub">Back to my setup</button>`)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-weapon-preview]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const w=WEAPONS.find(w=>w.id===b.dataset.weaponPreview);if(!w)return;openModal(`${topModal('WEAPON PREVIEW')}<h2 id="modal-title">${w.name}</h2><div class="weapon-large">${weaponIllustration(w,true)}</div><p class="sub">${w.desc}</p><p>${w.shots} projectile${w.shots===1?'':'s'} per trigger · Range ${w.range} · Unlock level ${w.level}</p><p class="notice">Illustrated firing demonstration. Previewing does not change your equipped weapon.</p><button class="primary" data-custom="weapons">Back to weapons</button>`)} ,true);
refreshPetNavigation();

const petShopBase=creditShop;creditShop=function(tab='armour'){petShopBase(tab);const list=({armour:ARMOUR_ITEMS,shield:SHIELD_ITEMS,style:STYLE_PACKS})[tab];if(!list)return;document.querySelectorAll('.shop-item-icon').forEach((el,i)=>{const item=list[i];if(!item)return;const colour=item.colour||'#a9d9cc';el.innerHTML=`<svg viewBox="0 0 100 100" aria-hidden="true"><ellipse cx="50" cy="88" rx="33" ry="7" fill="#061a3266"/><g stroke="#17354a" stroke-width="4" stroke-linejoin="round">${tab==='shield'?`<path d="M15 20 50 8 85 20v28Q85 75 50 91 15 75 15 48Z" fill="${colour}"/><path d="m50 24 7 14 16 2-12 11 3 16-14-8-14 8 3-16-12-11 16-2Z" fill="#ffdf97"/>`:tab==='armour'?`<path d="m27 12 23 9 23-9 18 22-16 17-5 36H30l-5-36L9 34Z" fill="${colour}"/><path d="M35 33h30v31H35Z" fill="#e1e8d6"/><path d="M50 33v31M31 73h38"/>`:`<circle cx="50" cy="46" r="32" fill="${colour}"/><path d="m50 22 8 16 18 3-13 13 3 19-16-9-16 9 3-19-13-13 18-3Z" fill="#ffdf97"/>`}</g></svg>`})};
// Bold navigation badges: cropped pet faces stay legible at touch-navigation sizes.
const smallPetNavArt=petNavArt;
petNavArt=function(kind){const face=id=>heroSVG(id).replace('viewBox="0 0 220 250"','viewBox="28 12 166 148"');if(kind==='heroes')return `<span aria-hidden="true" class="nav-badge nav-badge-avatar"><span class="nav-pet-face">${face(profile.hero)}</span><b class="nav-star">✦</b></span>`;if(kind==='live'){const other=HEROES.find(h=>h.id.startsWith(profile.hero.startsWith('dog')?'cat':'dog'))||HEROES[0];return `<span aria-hidden="true" class="nav-badge nav-badge-live"><span class="nav-teammate nav-teammate-back">${face(other.id)}</span><span class="nav-teammate nav-teammate-front">${face(profile.hero)}</span><b class="nav-online-dot"></b></span>`}if(kind==='home')return `<span aria-hidden="true" class="nav-badge nav-badge-play"><svg viewBox="0 0 80 80"><path d="M17 29Q10 30 8 43L5 59Q5 69 15 66L28 55h24l13 11Q75 69 75 59L72 43Q70 30 63 29Z" fill="#53d6cc" stroke="#143c59" stroke-width="4"/><path d="M15 38Q27 30 39 36" fill="none" stroke="#dcfff5" stroke-width="3" stroke-linecap="round"/><path d="M23 41v14m-7-7h14" stroke="#174769" stroke-width="5" stroke-linecap="round"/><circle cx="57" cy="42" r="4" fill="#fff09e"/><circle cx="65" cy="51" r="4" fill="#f599bb"/><circle cx="41" cy="23" r="19" fill="#ffdc75" stroke="#173b57" stroke-width="3"/><path d="m37 13 14 10-14 10Z" fill="#284b67"/></svg></span>`;return smallPetNavArt(kind)};
refreshPetNavigation();

